package filterlang

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/alphaleonis/nibs/internal/nib"
)

// OutputPath is the module-root-relative path of the generated file.
const OutputPath = "web/src/lib/generated/filterTokens.ts"

// Render returns the full generated TypeScript module.
//
// The token tables render `as const`, so the web's compile-time guards read
// each entry's literal field name.
func Render() string {
	var b strings.Builder
	b.WriteString(header)

	sets := make([]string, len(valueSets))
	for i, v := range valueSets {
		sets[i] = jsString(string(v))
	}
	b.WriteString("/** The vocabulary a metadata field's values come from. `tags` values match TAG_VALUE_PATTERN instead of a list. */\n")
	fmt.Fprintf(&b, "export type FilterValueSet = %s;\n\n", strings.Join(sets, " | "))

	b.WriteString("/** The metadata field tokens in canonical order, which is also the serialization order. */\n")
	b.WriteString("export const FILTER_FIELDS = [\n")
	for _, f := range fields {
		fmt.Fprintf(&b, "  { name: %s, filterKey: %s, excludeKey: %s, valueSet: %s },\n",
			jsString(f.Name), jsString(f.FilterKey), jsString(f.ExcludeKey), jsString(string(f.Values)))
	}
	b.WriteString("] as const satisfies readonly {\n")
	b.WriteString("  readonly name: string;\n")
	b.WriteString("  readonly filterKey: string;\n")
	b.WriteString("  readonly excludeKey: string;\n")
	b.WriteString("  readonly valueSet: FilterValueSet;\n")
	b.WriteString("}[];\n\n")

	b.WriteString("/** The pattern a `tags` value matches in full (Go nib.TagPattern). */\n")
	fmt.Fprintf(&b, "export const TAG_VALUE_PATTERN = new RegExp(%s);\n\n", jsString(nib.TagPattern))

	b.WriteString("/** The relationship-id and existence tokens in canonical serialization order. */\n")
	b.WriteString("export const REL_TOKENS = [\n")
	for _, t := range relTokens {
		switch t.Kind {
		case RelID:
			fmt.Fprintf(&b, "  { kind: %s, field: %s, name: %s, description: %s", jsString(string(t.Kind)), jsString(t.Field), jsString(t.Name), jsString(t.Description))
			if t.SearchTypes != nil {
				fmt.Fprintf(&b, ", searchTypes: %s", jsStrings(t.SearchTypes))
			}
			b.WriteString(" },\n")
		case RelBool:
			fmt.Fprintf(&b, "  { kind: %s, field: %s, token: %s, value: %t, description: %s },\n", jsString(string(t.Kind)), jsString(t.Field), jsString(t.Token), t.Value, jsString(t.Description))
		}
	}
	b.WriteString("] as const;\n\n")

	b.WriteString("/** The ownership tokens in canonical serialization order, the broad reading first. */\n")
	b.WriteString("export const AREA_TOKENS = [\n")
	for _, t := range areaTokens {
		fmt.Fprintf(&b, "  { name: %s, field: %s, description: %s },\n", jsString(t.Name), jsString(t.Field), jsString(t.Description))
	}
	b.WriteString("] as const;\n\n")

	b.WriteString("/** One row of the filter box's syntax help. */\n")
	b.WriteString("export interface FilterHelpRow {\n")
	b.WriteString("  readonly token: string;\n")
	b.WriteString("  readonly description: string;\n")
	b.WriteString("}\n\n")
	b.WriteString("/** The syntax help's operator rows in display order. */\n")
	writeHelpRows(&b, "HELP_OPERATORS", helpOperators)
	b.WriteString("\n/** The syntax help's example queries in display order. Each one parses with no invalid token. */\n")
	writeHelpRows(&b, "HELP_EXAMPLES", helpExamples)

	return b.String()
}

const header = `// Code generated by internal/filterlang. DO NOT EDIT.
// Regenerate with ` + "`task codegen`" + `.
//
// The filter language's token tables, rendered from the Go definitions in
// internal/filterlang. The committed file is pinned byte-for-byte by
// TestGeneratedFilterTokensAreFresh.

`

func writeHelpRows(b *strings.Builder, name string, rows []HelpRow) {
	fmt.Fprintf(b, "export const %s: readonly FilterHelpRow[] = [\n", name)
	for _, r := range rows {
		fmt.Fprintf(b, "  { token: %s, description: %s },\n", jsString(r.Token), jsString(r.Description))
	}
	b.WriteString("];\n")
}

// jsString quotes s as a JavaScript string literal. HTML escaping stays off so
// a `<` or `&` in help text renders as itself in the source.
func jsString(s string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		panic(err) // Encoding a string cannot fail.
	}
	return strings.TrimSuffix(buf.String(), "\n")
}

func jsStrings(values []string) string {
	quoted := make([]string, len(values))
	for i, v := range values {
		quoted[i] = jsString(v)
	}
	return "[" + strings.Join(quoted, ", ") + "]"
}
